// /js/logo.js
// Logo del proyecto, quemado en Base64 para que siempre se vea
// sin importar quién descargue o clone el repositorio.
const LOGO_BASE64 = "data:image/png;base64,";

document.addEventListener("DOMContentLoaded", () => {
    document.querySelectorAll(".logo-placeholder").forEach(el => {
        el.innerHTML = '<img src="' + LOGO_BASE64 + '" alt="Logo Equipo Charlie" style="height: 100px; width: auto; object-fit: contain;">';
    });
});